-- SOLO STAGING: importación de préstamos históricos ficticios con fechas y abonos exactos.
alter table public.cy_loans
 add column if not exists demo_origin text not null default 'NEW_DEMO'
 check (demo_origin in ('NEW_DEMO','HISTORICAL_DEMO'));

create table if not exists public.cc_clan_cobra_demo_imports(
 request_id uuid primary key,
 loan_id uuid not null unique references public.cy_loans(id) on delete cascade,
 user_id uuid not null references auth.users(id),
 client_id uuid not null,
 principal numeric(14,2) not null,
 issued_on date not null,
 schedule jsonb not null,
 imported_at timestamptz not null default now()
);
alter table public.cc_clan_cobra_demo_imports enable row level security;
revoke all on public.cc_clan_cobra_demo_imports from public,anon,authenticated;
grant all on public.cc_clan_cobra_demo_imports to service_role;

CREATE OR REPLACE FUNCTION public.cc_clan_cobra_import_historical_demo(p_user_id uuid, p_client_id uuid, p_request_id uuid, p_principal numeric, p_issued_on date, p_schedule jsonb)\n RETURNS uuid\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\ndeclare\n v_old public.cc_clan_cobra_demo_imports%rowtype;\n v_loan_id uuid;\n v_item jsonb;\n v_index integer:=0;\n v_amount numeric;\n v_paid numeric;\n v_due date;\n v_last_due date;\n v_sum numeric:=0;\n v_paid_sum numeric:=0;\n v_count integer;\n v_interest numeric;\nbegin\n if current_user<>'service_role' then raise exception 'Server-only historical demo import';end if;\n if p_user_id is null or p_client_id is null or p_request_id is null\n or p_principal is null or p_principal<>round(p_principal,2)\n or p_principal<10 or p_principal>10000\n or p_issued_on is null or p_issued_on < date '1990-01-01' or p_issued_on>current_date\n or p_schedule is null or jsonb_typeof(p_schedule)<>'array'\n or jsonb_array_length(p_schedule) not between 1 and 36 then\n  raise exception 'Invalid historical demo import';\n end if;\n perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(\n   'clan-cobra-historical-demo:'||p_request_id::text,0));\n select * into v_old from public.cc_clan_cobra_demo_imports\n where request_id=p_request_id for update;\n if found then\n  if v_old.user_id<>p_user_id or v_old.client_id<>p_client_id\n   or v_old.principal<>p_principal or v_old.issued_on<>p_issued_on\n   or v_old.schedule<>p_schedule\n  then raise exception 'Historical import ID reused with different details'; end if;\n  return v_old.loan_id;\n end if;\n if not exists(select 1 from public.cc_clan_cobra_access_periods\n where user_id=p_user_id and starts_at<=now() and ends_at>now())\n then raise exception 'Active COBRA YA subscription required';end if;\n if not exists(select 1 from public.cy_clients\n where id=p_client_id and owner_id=p_user_id and alias='DEMO')\n then raise exception 'Only own fictitious clients are permitted';end if;\n v_count:=jsonb_array_length(p_schedule);\n for v_item in select value from jsonb_array_elements(p_schedule) as t(value) loop\n  v_index:=v_index+1;\n  if jsonb_typeof(v_item)<>'object'\n    or (select count(*) from jsonb_object_keys(v_item) as k)<>3\n    or not (v_item ?& array['due_on','amount','paid_total'])\n    or jsonb_typeof(v_item->'due_on')<>'string'\n    or jsonb_typeof(v_item->'amount')<>'number'\n    or jsonb_typeof(v_item->'paid_total')<>'number'\n    or (v_item->>'due_on') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'\n  then raise exception 'Invalid installment %',v_index;end if;\n  v_due:=(v_item->>'due_on')::date;\n  v_amount:=(v_item->>'amount')::numeric;\n  v_paid:=(v_item->>'paid_total')::numeric;\n  if v_due<p_issued_on or v_due>current_date+interval '15 years'\n   or (v_last_due is not null and v_due < v_last_due)\n   or v_amount<=0 or v_amount>20000 or v_amount<>round(v_amount,2)\n   or v_paid<0 or v_paid>v_amount or v_paid<>round(v_paid,2)\n   then raise exception 'Invalid date/amount/paid for installment %',v_index; end if;\n  v_sum:=v_sum+v_amount;\n  v_paid_sum:=v_paid_sum+v_paid;\n  v_last_due:=v_due;\n end loop;\n if v_sum<p_principal or v_sum>50000 then\n  raise exception 'Installment total cannot be smaller than principal or above demo limit';end if;\n v_interest:=round((v_sum-p_principal)/p_principal*100,2);\n if v_interest>12000 then raise exception 'Historical effective interest too large';end if;\n insert into public.cy_loans(\n  owner_id,client_id,principal,interest_rate,term_installments,currency,\n  issued_on,first_due_on,interval_months,calculation_method,total_due,\n  status,created_at,demo_request_id,demo_origin\n ) values(\n  p_user_id,p_client_id,p_principal,v_interest,v_count,'PEN',\n  p_issued_on,(p_schedule->0->>'due_on')::date,1,'FLAT_SIMPLE',v_sum,\n  case when v_paid_sum=v_sum then 'CLOSED' else 'ACTIVE' end,\n  now(),p_request_id,'HISTORICAL_DEMO'\n ) returning id into v_loan_id;\n v_index:=0;\n for v_item in select value from jsonb_array_elements(p_schedule) as t(value) loop\n  v_index:=v_index+1;\n  v_amount:=(v_item->>'amount')::numeric;\n  v_paid:=(v_item->>'paid_total')::numeric;\n  insert into public.cy_installments(\n   loan_id,owner_id,installment_number,due_on,amount,paid_total,status\n  ) values(\n   v_loan_id,p_user_id,v_index,(v_item->>'due_on')::date,v_amount,v_paid,\n   case when v_paid=v_amount then 'PAID'\n        when v_paid>0 then 'PARTIAL' else 'PENDING' end\n  );\n end loop;\n insert into public.cc_clan_cobra_demo_imports(\n request_id,loan_id,user_id,client_id,principal,issued_on,schedule\n ) values(\n p_request_id,v_loan_id,p_user_id,p_client_id,p_principal,p_issued_on,p_schedule);\n return v_loan_id;\nend $function$\n
revoke all on function public.cc_clan_cobra_import_historical_demo(
 uuid,uuid,uuid,numeric,date,jsonb) from public,anon,authenticated;
grant execute on function public.cc_clan_cobra_import_historical_demo(
 uuid,uuid,uuid,numeric,date,jsonb) to service_role;
